      },
      {
        "fonte_id": "f_a781",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "A restrição D10 e a duração de três dias situam o término mais cedo do dossiê em D13, mas não foram fornecidas as precedências da ficha d_a70f para determinar seu efeito sobre o marco final."
    ],
    "motivo": "O aviso altera a restrição do dossiê; sem as relações de precedência, não é possível determinar o término do marco final.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_355a6d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Faltam as precedências da ficha d_a70f; não é possível estabelecer se nem quanto a alteração do dossiê muda o término final."
    ],
    "motivo": "A mudança da restrição está evidenciada, mas seu efeito no término final depende de relações de precedência não apresentadas.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "Custo base declarado como R$ 1.650,00, equivalente a 165000 centavos.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_355a6d",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "O aviso mantém as demais obrigações; os custos são esgotados pelas parcelas fixas e pelo apoio, cuja política não concede crédito sem aditivo expresso.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": 0,
    "direcao": "zero",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_355a6d",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "O aviso não altera custos ou obrigações, e não há aditivo expresso de recálculo do apoio.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O efeito do aviso sobre o término final não pode ser propagado sem as precedências da ficha d_a70f. O custo permanece igual à linha base porque as obrigações e a política do apoio não foram alteradas."
}

